#!/usr/bin/env python3
# ******************************************************************************
# * @file    data.py
# * @author  Simeon Marlokov
# * @brief   Reads the qAI seed fixture (fixtures/qai_seed.json). The fixture is
# *          generated by fixtures/build_qai_seed.py from docs/seed/SEED_SCENARIO.md;
# *          nothing here is hand-written data.
# * @date    26.10.2026
# ******************************************************************************
import json
from functools import cache
from pathlib import Path
from typing import Any

from src.models.ticket import TicketPriority, TicketStatus

FIXTURE_PATH = Path(__file__).with_name("fixtures") / "qai_seed.json"

# Techniques of the adversarial tickets, as named in the fixture's `adversarial.technique`.
ADVERSARIAL_TECHNIQUES = frozenset(
    {
        "delete-and-reveal",
        "fake-system-message",
        "markdown-exfiltration",
        "fake-authority",
        "field-smuggling-hidden-comment",
        "poisoned-summary",
        "instruction-in-title",
        "self-approval",
    }
)


@cache
def load_seed(path: Path = FIXTURE_PATH) -> dict[str, Any]:
    """The parsed fixture. Cached: the file is 400 KB and read on every seed run and in tests."""
    with path.open(encoding="utf-8") as handle:
        seed = json.load(handle)
    _check(seed)
    return seed


def status_value(name: str) -> int:
    return TicketStatus[name].value


def priority_value(name: str) -> int:
    return TicketPriority[name].value


def adversarial_tickets(seed: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    seed = seed or load_seed()
    return [ticket for ticket in seed["tickets"] if ticket.get("adversarial")]


def _check(seed: dict[str, Any]) -> None:
    """Cheap structural checks so a broken fixture fails before the first INSERT."""
    required = ("organizations", "users", "tickets", "revisions", "pending_revisions", "discussions")
    missing = [key for key in required if key not in seed]
    if missing:
        raise ValueError(f"seed fixture is missing sections: {', '.join(missing)}")
    organization_keys = {organization["key"] for organization in seed["organizations"]}
    user_keys = {user["key"] for user in seed["users"]}
    refs = set()
    for ticket in seed["tickets"]:
        if ticket["organization"] not in organization_keys:
            raise ValueError(f"{ticket['ref']} points at unknown organization {ticket['organization']}")
        if ticket["updated_by"] is not None and ticket["updated_by"] not in user_keys:
            raise ValueError(f"{ticket['ref']} updated by unknown user {ticket['updated_by']}")
        status_value(ticket["status"])
        priority_value(ticket["priority"])
        refs.add(ticket["ref"])
    for section in ("revisions", "pending_revisions", "discussions"):
        for row in seed[section]:
            if row["ticket_ref"] not in refs:
                raise ValueError(f"{section} row points at unknown ticket {row['ticket_ref']}")
            if row["user"] not in user_keys:
                raise ValueError(f"{section} row by unknown user {row['user']}")
